<?php
$config=require __DIR__.'/site-runtime.php';
$path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH)?:'/';
$path='/'.trim($path,'/');
header('Content-Type: text/html; charset=utf-8');
header('Cache-Control: no-cache');
function esc($v){return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function api($config,$path){if(empty($config['url'])||empty($config['key']))return null;$ch=curl_init($config['url'].'/rest/v1/'.$path);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>6,CURLOPT_HTTPHEADER=>['apikey: '.$config['key']]]);$raw=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);return $status===200?json_decode($raw,true):null;}
function clean_body($html){$html=preg_replace('#<(script|style|iframe|object|embed)[^>]*>.*?</\1>#is','',$html);$html=strip_tags($html,'<p><h2><h3><h4><ul><ol><li><strong><b><em><i><a><blockquote><img><figure><figcaption><br><hr><table><thead><tbody><tr><th><td>');if(!class_exists('DOMDocument'))return esc(strip_tags($html));$doc=new DOMDocument();libxml_use_internal_errors(true);$doc->loadHTML('<?xml encoding="utf-8"?><div>'.$html.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);foreach($doc->getElementsByTagName('*') as $el){foreach(iterator_to_array($el->attributes) as $attr){$name=strtolower($attr->name);$value=$attr->value;$allowed=in_array($name,['href','src','alt','width','height']);if(in_array($name,['href','src'])&&!preg_match('#^(https?://|/(?!/))#i',$value))$allowed=false;if(!$allowed)$el->removeAttribute($attr->name);}if($el->tagName==='a')$el->setAttribute('rel','noopener noreferrer');}return preg_replace('/<\?xml[^>]*>/', '',$doc->saveHTML());}
$isArticle=preg_match('#^/conteudos/([a-z0-9]+(?:-[a-z0-9]+)*)$#',$path,$match);
$post=null;
if($isArticle){$rows=api($config,'content_posts?select=*&slug=eq.'.rawurlencode($match[1]).'&status=eq.published&published_at=lte.'.rawurlencode(gmdate('c')).'&limit=1');if(is_array($rows)&&!count($rows)){http_response_code(404);readfile(__DIR__.'/404/index.html');exit;}$post=$rows[0]??null;}
$file=$path==='/'?__DIR__.'/index.html':__DIR__.$path.'/index.html';
if(!is_file($file)){if(!$post){http_response_code(404);$file=__DIR__.'/404/index.html';}else $file=__DIR__.'/index.html';}
$html=file_get_contents($file);
if(str_starts_with($path,'/admin')){header('Cache-Control: private, no-store');header('X-Robots-Tag: noindex, nofollow');}
if($post){$title=($post['seo_title']?:$post['title']).' | Legenda Digital';$description=$post['seo_description']?:$post['excerpt'];$url='https://legendadigital.com.br'.$path;$image=$post['featured_image'];if(str_starts_with($image,'/'))$image='https://legendadigital.com.br'.$image;$head='<meta name="description" content="'.esc($description).'"><link rel="canonical" href="'.esc($url).'"><meta property="og:title" content="'.esc($title).'"><meta property="og:description" content="'.esc($description).'"><meta property="og:url" content="'.esc($url).'"><meta property="og:image" content="'.esc($image).'"><meta property="og:type" content="article"><meta name="twitter:card" content="summary_large_image">';$schema=['@context'=>'https://schema.org','@type'=>'Article','headline'=>$post['title'],'description'=>$description,'image'=>$image,'datePublished'=>$post['published_at'],'dateModified'=>$post['updated_at'],'author'=>['@type'=>'Organization','name'=>$post['author']],'publisher'=>['@type'=>'Organization','name'=>'Legenda Digital'],'mainEntityOfPage'=>$url];$head.='<script type="application/ld+json">'.json_encode($schema,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE).'</script>';$html=preg_replace('#<title>.*?</title>#s','<title>'.esc($title).'</title>',$html);$html=preg_replace('#<meta (?:name="description"|property="og:[^"]+"|name="twitter:[^"]+")[^>]*>|<link rel="canonical"[^>]*>|<script type="application/ld\+json">.*?</script>#s','',$html);$html=str_replace('</head>',$head.'</head>',$html);$body='<header class="site-header"><div class="container header-inner"><a class="logo" href="/" aria-label="Legenda Digital — início"><img class="brand-logo" src="/images/legenda-digital-logo.png" width="2048" height="682" alt="Legenda Digital"></a><a href="/conteudos">Conteúdos</a><a href="/newsletter">LD Brief</a></div></header><main id="conteudo"><section class="article-head container"><nav class="breadcrumbs"><a href="/">Início</a> / <a href="/conteudos">Conteúdos</a></nav><span class="category">'.esc($post['category']).'</span><h1>'.esc($post['title']).'</h1><p>'.esc($post['excerpt']).'</p><div class="article-meta">'.esc($post['author']).' · '.esc(substr($post['published_at'],0,10)).' · '.intval($post['reading_time']).' min</div></section><div class="container article-hero"><img src="'.esc($post['featured_image']).'" alt="'.esc($post['title']).'" width="1200" height="700"></div><article class="article-body container narrow">'.clean_body($post['body']).'</article><section class="section container"><a class="btn btn-primary" href="/newsletter">Assinar LD Brief</a></section></main>';$start=strpos($html,'<div id="root">');$end=strrpos($html,'</div>');if($start!==false&&$end!==false)$html=substr($html,0,$start).'<div id="root">'.$body.'</div>'.substr($html,$end+6);}
echo $html;

